from copy import deepcopy
from dataclasses import dataclass


@dataclass(frozen=True)
class EntryOptions:
    title: str
    curator: str | None = None
    tags: tuple[str, ...] = ()
    attributes: dict[str, object] | None = None


def build_entry(kind: str, options: EntryOptions) -> dict:
    if not isinstance(kind, str):
        raise TypeError("kind must be a string")
    if kind not in {"book", "audio", "map"}:
        raise ValueError("unsupported kind")
    if not isinstance(options, EntryOptions):
        raise TypeError("options must be EntryOptions")
    if not isinstance(options.title, str):
        raise TypeError("title must be a string")
    title = options.title.strip()
    if not title:
        raise ValueError("title cannot be blank")
    if options.curator is not None and not isinstance(options.curator, str):
        raise TypeError("curator must be a string or None")
    curator = options.curator.strip() if options.curator is not None else None
    if curator == "":
        raise ValueError("curator cannot be blank")
    if not isinstance(options.tags, tuple):
        raise TypeError("tags must be a tuple")

    tags = []
    for tag in options.tags:
        if not isinstance(tag, str):
            raise TypeError("tags must contain strings")
        clean = tag.strip()
        if not clean:
            raise ValueError("tags cannot be blank")
        if clean in tags:
            raise ValueError("tags cannot be duplicated")
        tags.append(clean)

    if options.attributes is not None and not isinstance(options.attributes, dict):
        raise TypeError("attributes must be a dictionary or None")

    return {
        "kind": kind,
        "title": title,
        "curator": curator,
        "tags": tags,
        "attributes": deepcopy(options.attributes) if options.attributes is not None else {},
    }
